import{_ as a,C as d,o as c,c as s,a5 as t,E as i}from"./chunks/framework.DSg0KOwT.js";const _=JSON.parse('{"title":"list_detectors","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/mcp-tools/list-detectors.md","filePath":"user-guide/mcp-tools/list-detectors.md"}'),r={name:"user-guide/mcp-tools/list-detectors.md"};function n(l,e,h,p,u,g){const o=d("DetectorMcpExample");return c(),s("div",null,[e[0]||(e[0]=t('<h1 id="list-detectors" tabindex="-1"><code>list_detectors</code> <a class="header-anchor" href="#list-detectors" aria-label="Permalink to &quot;`list_detectors`&quot;">​</a></h1><p>Reference for the <code>list_detectors</code> tool of the SparkForensics MCP server.</p><p>Every finding type the detectors can report, independent of any run: what it finds, how it is grouped, its default thresholds, where its docs live and the budget flag that gates it. An agent can call it to learn what SparkForensics checks before it loads a run. The same list is on the command line as <a href="./../getting-started/ci-and-automation.html#list-the-detectors"><code>sparkforensics-analyze detectors</code></a> and as the <a href="./../../detectors/">detector catalog</a> pages of this site.</p><p>Parameter, optional:</p><ul><li><code>type</code>: one finding <code>type</code> value, such as <code>&quot;skew&quot;</code>. An unknown type fails input validation. Without it the tool returns every type.</li></ul>',5)),i(o,{type:"skew"}),e[1]||(e[1]=t('<p>Each record has:</p><ul><li><code>type</code>, <code>name</code>, <code>tag</code> and <code>tagSharedWith</code>, the other types that share the tag.</li><li><code>family</code> and <code>pitch</code>: the outcome group and one sentence on what the finding means.</li><li><code>region</code>: <code>&quot;reference&quot;</code> for the types the dashboard shows below its action widgets, <code>&quot;action&quot;</code> for the rest.</li><li><code>scope</code> and <code>fixEffort</code>: where the detector looks, and whether the fix is a setting (<code>config</code>) or a change to the job (<code>code</code>).</li><li><code>thresholdSummary</code> and <code>detectors</code>: the clean-check criterion, and one entry per detector that emits the type with its version and default thresholds. A type can have several entries (<code>configAudit</code> has several). A server started with <code>--thresholds</code> still lists the defaults here; its analyzing tools report the tuned values.</li><li><code>pages</code>: the catalog page of the type and its entry in the findings guide, as paths under the site root.</li><li><code>tuning</code>: where the tuning reference covers the type, as a <code>page</code> of its own, a page <code>shared</code> with other types, a <code>section</code> of another page or a general <code>chapter</code>. It is <code>null</code> when no single anchor covers the type.</li><li><code>gate</code>: the CLI budget flag and the Airflow operator parameter that gate the type directly. It is <code>null</code> for the types with no budget; those are gated with <code>--fail-on-introduced</code> against a baseline.</li></ul><p>For the detection and tuning text of one type, call <a href="./get-finding-documentation.html"><code>get_finding_documentation</code></a>.</p>',3))])}const m=a(r,[["render",n]]);export{_ as __pageData,m as default};
